# 54 law firms: (slug, name, url, verified fact, observation 1, observation 2, slide notes [(text, fx, fy)])
import json, os
_P = os.path.join(os.path.dirname(__file__), 'notes.json')
_N = json.load(open(_P)) if os.path.exists(_P) else {}
_B = [
("cravath","Cravath","https://www.cravath.com/","Cravath, Swaine & Moore traces its roots to 1819 in New York and is one of the oldest firms on Wall Street.","Wide, classical capitals in navy feel like an engraving on a stone building.","Shortening the full partnership name to one word made the firm easier to say and remember."),
("paul-weiss","Paul Weiss","https://www.paulweiss.com/","Paul, Weiss, Rifkind, Wharton & Garrison was founded in New York in 1875.","The two names sit in a navy square, like a seal or an app icon.","The comma after Paul keeps a trace of the long partnership name."),
("sullivan-and-cromwell","Sullivan & Cromwell","https://www.sullcrom.com/","Algernon Sullivan and William Nelson Cromwell founded the firm in New York in 1879.","Small serif capitals feel formal and traditional.","The ampersand joins the two founders, the classic law firm formula."),
("davis-polk","Davis Polk","https://www.davispolk.com/","Davis Polk & Wardwell traces its history to 1849 in New York.","Very widely spaced small capitals feel quiet and elite.","Navy type on white is the most typical law firm palette."),
("skadden","Skadden","https://www.skadden.com/","Skadden, Arps, Slate, Meagher & Flom was founded in New York in 1948.","White serif letters on a bright red box make it the boldest logo in the group.","Using only the first name of a five-name partnership keeps the brand short."),
("wachtell-lipton","Wachtell Lipton","https://www.wlrk.com/","Wachtell, Lipton, Rosen & Katz was founded in New York in 1965.","All four names are stacked in small capitals inside a black box.","The plain black box looks like a nameplate on an office door."),
("simpson-thacher","Simpson Thacher","https://www.stblaw.com/","Simpson Thacher & Bartlett was founded in New York in 1884.","Large old-style serif letters are stacked on two lines.","The wordmark feels like the title page of a classic book."),
("cleary-gottlieb","Cleary Gottlieb","https://www.clearygottlieb.com/","Cleary Gottlieb Steen & Hamilton was founded in 1946 in New York and Washington.","Widely spaced capitals feel calm and modern.","Two names are kept from a four-name partnership."),
("milbank","Milbank","https://www.milbank.com/","Milbank was founded in New York in 1866.","A single heavy serif word looks confident and timeless.","The one-word name is easy to remember in a field of long partnerships."),
("kirkland-and-ellis","Kirkland & Ellis","https://www.kirkland.com/","Kirkland & Ellis was founded in Chicago in 1909 and is one of the highest-earning law firms in the world.","Small serif capitals feel classic and understated.","The quiet logo contrasts with the firm's size and reputation."),
("latham-and-watkins","Latham & Watkins","https://www.lw.com/","Dana Latham and Paul Watkins founded the firm in Los Angeles in 1934.","Red spaced capitals stand out from the usual navy of law firms.","A tiny ampersand between the names keeps the line tight."),
("dla-piper","DLA Piper","https://www.dlapiper.com/","DLA Piper was formed by a large merger in 2005 and is one of the world's biggest law firms.","A navy rounded shape holds the name like a speech bubble or a stone.","The bold sans serif feels more corporate than traditional."),
("baker-mckenzie","Baker McKenzie","https://www.bakermckenzie.com/","Russell Baker and John McKenzie founded the firm in Chicago in 1949.","Two heavy names are stacked and end with a full stop.","The full stop makes the name feel like a confident statement."),
("dentons","Dentons","https://www.dentons.com/","Dentons was formed by a merger in 2013 and became the world's largest law firm by number of lawyers.","Bold white capitals sit on a purple arrow shape.","Purple is very rare among law firms, which makes Dentons easy to spot."),
("white-and-case","White & Case","https://www.whitecase.com/","Justin DuPratt White and George Case founded the firm in New York in 1901.","Stacked letters with a bold W and ampersand feel custom-made.","The blue monogram-like lockup works well as an icon."),
("gibson-dunn","Gibson Dunn","https://www.gibsondunn.com/","Gibson, Dunn & Crutcher was founded in Los Angeles in 1890.","Bright blue capitals feel energetic for a law firm.","The two-name brand drops the third partner to stay short."),
("sidley","Sidley","https://www.sidley.com/","Sidley Austin was founded in Chicago in 1866.","Simple, strong capitals spell out one word.","Shortening the name to Sidley gives the firm a modern, confident brand."),
("jones-day","Jones Day","https://www.jonesday.com/","Jones Day traces its history to 1893 in Cleveland, Ohio.","Two words overlap in a tight serif monogram.","Stacking the names makes the logo compact and memorable."),
("clifford-chance","Clifford Chance","https://www.cliffordchance.com/","Clifford Chance was formed in London in 1987 through a merger.","Clean sans serif letters feel modern and corporate.","The firm uses no symbol at all, just the two names."),
("freshfields","Freshfields","https://www.freshfields.com/","Freshfields traces its roots to 1743 in London, and in 2024 it dropped \"Bruckhaus Deringer\" from its name.","Heavy, wide capitals make a strong, modern wordmark.","The rebrand turned a long name into one bold word."),
("linklaters","Linklaters","https://www.linklaters.com/","Linklaters was founded in London in 1838.","A bright magenta wordmark is the most colourful in the Magic Circle.","Rounded lowercase letters make the firm feel friendly and modern."),
("a-and-o-shearman","A&O Shearman","https://www.aoshearman.com/","A&O Shearman was formed in 2024 by the merger of Allen & Overy and Shearman & Sterling.","Dark green capitals combine an old monogram with a new name.","The short A&O keeps the recognition of Allen & Overy after the merger."),
("slaughter-and-may","Slaughter and May","https://www.slaughterandmay.com/","Slaughter and May was founded in London in 1889.","Spaced purple capitals feel calm and distinguished.","The word \"and\" is spelled out instead of using an ampersand."),
("herbert-smith-freehills-kramer","Herbert Smith Freehills Kramer","https://www.hsfkramer.com/","Herbert Smith Freehills Kramer was formed in 2025 by the merger of Herbert Smith Freehills and Kramer Levin.","A circle of blue lines looks like a burst of energy or a globe.","The long name is stacked into three short lines."),
("hogan-lovells","Hogan Lovells","https://www.hoganlovells.com/","Hogan Lovells was formed in 2010 by the merger of Hogan & Hartson and Lovells.","A bright lime-green square is unlike any other law firm logo.","The two names sit inside the square like a label."),
("norton-rose-fulbright","Norton Rose Fulbright","https://www.nortonrosefulbright.com/","Norton Rose Fulbright was formed in 2013 by a transatlantic merger.","Red capitals with a small roof-like mark above the N.","The long three-word name stays on one line."),
("withers","Withers","https://www.withersworldwide.com/","Withers was founded in London in 1896 and is known for advising wealthy families.","Lowercase letters with an orange underline feel modern and approachable.","The orange dot over the i adds a small, friendly accent."),
("cooley","Cooley","https://www.cooley.com/","Cooley was founded in San Francisco in 1920 and is known for advising tech startups and investors.","A heavy, round sans serif looks like a tech brand.","The lowercase-style letters feel friendly to startup founders."),
("wilson-sonsini","Wilson Sonsini","https://www.wsgr.com/","Wilson Sonsini Goodrich & Rosati was founded in Palo Alto in 1961.","Two names in bold spaced capitals are stacked on two lines.","The firm has been Silicon Valley's go-to startup lawyer for decades."),
("gunderson-dettmer","Gunderson Dettmer","https://www.gunder.com/","Gunderson Dettmer was founded in Silicon Valley in 1995 and focuses on venture-backed companies.","A blue GD monogram sits next to grey spaced capitals.","The grey name feels quiet and modern."),
("fenwick","Fenwick","https://www.fenwick.com/","Fenwick & West was founded in Silicon Valley in 1972 and now uses the shorter name Fenwick.","Heavy black capitals make one strong word.","Dropping \"& West\" made the firm feel like a modern tech brand."),
("orrick","Orrick","https://www.orrick.com/","Orrick, Herrington & Sutcliffe was founded in San Francisco in 1863.","A green ring sits above lowercase letters like a dot on an i.","The rounded lowercase name feels light and approachable."),
("goodwin","Goodwin","https://www.goodwinlaw.com/","Goodwin Procter was founded in Boston in 1912.","An orange G icon looks like a folded ribbon.","Spaced capitals next to the icon feel clean and modern."),
("fish-and-richardson","Fish & Richardson","https://www.fr.com/","Fish & Richardson was founded in Boston in 1878 and specialises in intellectual property.","Only the word FISH appears, followed by a teal dot.","Using the shortest name makes the logo bold and witty."),
("quinn-emanuel","Quinn Emanuel","https://www.quinnemanuel.com/","Quinn Emanuel Urquhart & Sullivan was founded in Los Angeles in 1986 and only does litigation.","Bold lowercase type with a green-gold name and the words \"trial lawyers\".","The unusual colour and tagline match the firm's aggressive reputation."),
("morrison-foerster","Morrison Foerster","https://www.mofo.com/","Morrison & Foerster was founded in San Francisco in 1883 and is often called MoFo.","Letters are built from lines with gaps, like a technical drawing.","The stencil-like style feels modern and inventive."),
("susman-godfrey","Susman Godfrey","https://www.susmangodfrey.com/","Susman Godfrey was founded in Houston in 1980 and focuses on high-stakes trials.","Spaced capitals sit on a thin red line.","The underline adds one accent to a very simple wordmark."),
("keker-van-nest-and-peters","Keker Van Nest & Peters","https://www.keker.com/","Keker, Van Nest & Peters was founded in San Francisco in 1978 and is known for trial work.","Three names are stacked between thin lines like a letterpress poster.","A small green ampersand adds one touch of colour."),
("boies-schiller-flexner","Boies Schiller Flexner","https://www.bsfllp.com/","David Boies co-founded Boies Schiller Flexner in 1997.","Big BSF initials sit next to the three names in light capitals.","The S has a sharp cut, a small custom detail."),
("selendy-gay","Selendy Gay","https://www.selendygay.com/","Jennifer Selendy, Philippe Selendy and Faith Gay founded Selendy Gay in New York in 2018.","A light, elegant serif splits the two names with a vertical line.","The thin type looks like a fashion brand more than a litigation firm."),
("wilkinson-stekloff","Wilkinson Stekloff","https://www.wilkinsonstekloff.com/","Beth Wilkinson founded Wilkinson Stekloff in Washington in 2016.","W and S letters sit in a blue column like building blocks.","The teal names next to it feel fresh and modern."),
("bartlit-beck","Bartlit Beck","https://www.bartlitbeck.com/","Bartlit Beck was founded in Chicago in 1993 and is known for its trial lawyers.","A navy serif joins the two names into one word.","A small LLP tucked at the end keeps the line clean."),
("mololamken","MoloLamken","https://www.mololamken.com/","Steven Molo and Jeffrey Lamken founded MoloLamken in 2009.","The two names are joined into one word in small capitals.","Wide spacing and thin strokes feel quiet and confident."),
("axinn","Axinn","https://www.axinn.com/","Axinn, Veltrop & Harkrider was founded in New York in 1997 and focuses on antitrust and IP.","Heavy, rounded lowercase letters make a bold, unusual wordmark.","The single name is short and easy to remember."),
("fox-berman","Fox Berman","https://www.foxberman.com/","Fox Berman is a boutique business and international law firm in Sint Maarten, in the Dutch Caribbean.","A custom all-capital wordmark designed by Ebaqdesign, with thin notches cut into the joints of the M, A and N.","The orange, called Tropical in the brand guidelines, stands for the island setting of Sint Maarten."),
("mori-hamada-and-matsumoto","Mori Hamada & Matsumoto","https://www.mhmjapan.com/","Mori Hamada & Matsumoto was formed in Tokyo in 2002 and is one of Japan's largest law firms.","The Japanese name is set in a classic serif above a red line.","The small English name below works for international clients."),
("nishimura-and-asahi","Nishimura & Asahi","https://www.nishimura.com/","Nishimura & Asahi is based in Tokyo and is one of Japan's largest law firms.","Green triangle accents frame spaced capitals.","The small corners feel like the edges of a document or a stamp."),
("garrigues","Garrigues","https://www.garrigues.com/","Garrigues was founded in Madrid in 1941 and is one of Spain's biggest law firms.","Dark green spaced capitals feel classic and calm.","A single family name gives the firm a strong brand."),
("uria-menendez","Uría Menéndez","https://www.uria.com/","Uría Menéndez was founded in Madrid in 1946.","Two names are stacked, with Menéndez in a fresh teal.","The accents on the letters keep the Spanish names authentic."),
("galicia-abogados","Galicia Abogados","https://www.galicia.com.mx/","Galicia Abogados is one of Mexico's leading corporate law firms, based in Mexico City.","A heavy, sharp serif makes the single name look strong.","The logo uses only Galicia, without the word for lawyers."),
("brigard-urrutia","Brigard Urrutia","https://www.bu.com.co/","Brigard Urrutia is one of Colombia's leading law firms, based in Bogotá.","Two names are stacked in a clean, humanist sans serif.","The simple type keeps the long Spanish names easy to read."),
("rajah-and-tann","Rajah & Tann","https://www.rajahtannasia.com/","Rajah & Tann was founded in Singapore in 1976 and now operates across Southeast Asia.","Two names are stacked with an orange Asia underneath.","The orange word shows the firm's regional reach."),
("torys","Torys","https://www.torys.com/","Torys was founded in Toronto in 1941.","Wide, thin serif capitals look classic and calm.","The short name works well as a single word."),
("bell-gully","Bell Gully","https://www.bellgully.com/","Bell Gully traces its roots to 1840 in Wellington and is one of New Zealand's oldest law firms.","Heavy, condensed serif letters join the two names.","The tight spacing makes the logo feel bold and solid."),
]
B = [t + (_N.get(t[0], []),) for t in _B]
assert len(B) == 54
